'use client';

import React from 'react';
import Link from 'next/link';
import { ShoppingCart, Check } from 'lucide-react';
import { ShopItem } from '../types';
import { formatCurrency } from '@/utils';
import { useCart } from '../context/CartContext';
import { useState } from 'react';

interface ProductCardProps {
    item: ShopItem;
}

export const ProductCard: React.FC<ProductCardProps> = ({ item }) => {
    const { addToCart } = useCart();
    const [added, setAdded] = useState(false);

    const handleAddToCart = () => {
        // For quick add, we use empty/default selections
        const defaultSelections: Record<string, string> = {};
        item.options?.forEach(opt => {
            if (opt.type === 'select' && opt.choices) {
                defaultSelections[opt.id] = opt.choices[0];
            }
        });

        addToCart(item, defaultSelections);
        setAdded(true);
        setTimeout(() => setAdded(false), 2000);
    };

    return (
        <div className="bg-white rounded-3xl border border-slate-100 overflow-hidden shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all duration-300 group">
            {/* Image Container */}
            <div className="h-64 bg-slate-100 relative overflow-hidden">
                <img
                    src={item.image}
                    alt={item.name}
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                />
            </div>

            {/* Content */}
            <div className="p-6 space-y-4">
                <div className="space-y-2 min-h-[100px]">
                    <h3 className="text-lg font-black text-slate-900 tracking-tight leading-tight group-hover:text-emerald-600 transition-colors">
                        {item.name}
                    </h3>
                    <p className="text-sm text-slate-500 font-medium leading-relaxed line-clamp-2">
                        {item.shortDescription}
                    </p>
                </div>

                <div className="flex items-center justify-between">
                    <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Starting from</p>
                        <p className="text-2xl font-black text-emerald-600 tracking-tighter">
                            {formatCurrency(item.price)}
                            {item.billingType === 'MONTHLY' && <span className="text-xs text-slate-400 ml-1">/mo</span>}
                        </p>
                    </div>
                    <div className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${item.stockStatus === 'In Stock' ? 'bg-emerald-50 text-emerald-600' :
                        item.stockStatus === 'Best Seller' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' :
                            'bg-rose-50 text-rose-600'
                        }`}>
                        {item.stockStatus}
                    </div>
                </div>

                <div className="grid grid-cols-5 gap-2 pt-2">
                    <button
                        onClick={handleAddToCart}
                        className={`col-span-2 flex items-center justify-center gap-2 h-12 rounded-2xl text-xs font-black transition-all active:scale-95 ${added ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                            }`}
                    >
                        {added ? <Check size={16} /> : <ShoppingCart size={16} />}
                        {added ? 'Added' : 'Add to Cart'}
                    </button>
                    <Link
                        href={`/shop/${item.category}/${item.id}`}
                        className="col-span-3 flex items-center justify-center h-12 bg-emerald-600 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all hover:bg-emerald-700 active:scale-95 shadow-lg shadow-emerald-100"
                    >
                        Customize
                    </Link>
                </div>
            </div>
        </div>
    );
};
